import java.util.*;
import java.io.*;

public class Main {
    static final int MAXN = (1 << 20) + 7;
    static final int MAXK = 20;
    static final int INF = (int)1e9 + 7;
    static final long LLINF = (long)1e18 + 7L;
    static final double EPS = 1e-9;
    static final long MOD = 1000000007L;

    static int[][] table = new int[MAXK + 1][MAXK + 1];
    static int[][] elo = new int[MAXK + 1][MAXK + 1];
    static int[] maska = new int[MAXN];

    static long[][] dp = new long[MAXN][2];

    static long power(long base, long exponent) {
        if (exponent == 0) return 1;
        long half = power(base, exponent / 2);
        long result = (half * half) % MOD;
        if ((exponent & 1) == 1) result = (result * base) % MOD;
        return result;
    }

    static int compute_mask(List<int[]> edges, boolean flag) {
        int mask_value = 0;
        int size = edges.size();
        for (int i = 0; i < size; i++) {
            int[] edge_i = edges.get(i);
            for (int j = i + 1; j < size; j++) {
                int[] edge_j = edges.get(j);
                if (edge_i[0] != edge_j[0] && edge_i[1] != edge_j[1]) {
                    for (int k = j + 1; k < size; k++) {
                        int[] edge_k = edges.get(k);
                        if (edge_i[0] != edge_k[0] && edge_j[0] != edge_k[0]
                                && edge_i[1] != edge_k[1] && edge_j[1] != edge_k[1]) {
                            int val = (1 << edge_i[1]) ^ (1 << edge_j[1]) ^ (1 << edge_k[1]);
                            mask_value |= maska[(flag ? 126 : 0) ^ val];
                        }
                    }
                }
            }
        }
        return mask_value;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st;

        int n = Integer.parseInt(br.readLine().trim());
        for (int i = 1; i <= n; i++) {
            st = new StringTokenizer(br.readLine());
            for (int j = 1; j <= n; j++) {
                table[i][j] = Integer.parseInt(st.nextToken());
            }
        }

        int counter = 0;
        for (int i = 1; i <= 6; i++) {
            for (int j = i + 1; j <= 6; j++) {
                for (int k = j + 1; k <= 6; k++) {
                    int val = ((1 << i) ^ (1 << j) ^ (1 << k));
                    maska[val] = (1 << counter++);
                }
            }
        }

        for (int i = n + 1; i <= 6; i++) {
            table[i][i] = 100;
        }

        List<int[]> edges = new ArrayList<>();
        n = 6;
        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= n; j++) {
                edges.add(new int[]{i, j});
            }
        }

        long inv_100 = power(100, MOD - 2);

        for (int k = 0; k < 2; k++) {
            for (int mask_idx = 0; mask_idx < (1 << 18); mask_idx++) {
                long prob = 1;
                List<int[]> selected_edges = new ArrayList<>();
                for (int j = 0; j < 18; j++) {
                    if (((1 << j) & mask_idx) != 0) {
                        int[] edge = edges.get(j + k * 18);
                        long val = table[edge[0]][edge[1]];
                        prob = (prob * val) % MOD;
                        prob = (prob * inv_100) % MOD;
                        selected_edges.add(edge);
                    } else {
                        int[] edge = edges.get(j + k * 18);
                        long val = table[edge[0]][edge[1]];
                        long temp = (100 - val + MOD) % MOD;
                        prob = (prob * temp) % MOD;
                        prob = (prob * inv_100) % MOD;
                    }
                }
                int current_mask = compute_mask(selected_edges, k == 1);
                dp[current_mask][k] = (dp[current_mask][k] + prob) % MOD;
            }
        }

        long result = 1;
        for (int i = 0; i < 20; i++) {
            for (int j = 0; j < (1 << 20); j++) {
                if (((1 << i) & j) != 0) {
                    dp[j][0] = (dp[j][0] + dp[j ^ (1 << i)][0]) % MOD;
                }
            }
        }

        for (int i = 0; i < (1 << 20); i++) {
            long val1 = dp[i][0];
            long val2 = dp[((1 << 20) - 1) ^ i][1];
            result = (result - (val1 * val2) % MOD + MOD) % MOD;
        }

        System.out.println(result);
    }
}
